function useItem(i){const it=game.state.inventory[i];if(!it||it.count<1)return;if(it.name==='Healing Potion'){if(game.state.hp===game.state.maxHp){toast('HP is already full.');return}const n=Math.min(35,game.state.maxHp-game.state.hp);game.state.hp+=n;toast(`Restored ${n} HP.`)}else if(it.name==='Minor SP Tonic'){if(game.state.sp===game.state.maxSp){toast('SP is already full.');return}const n=Math.min(18,game.state.maxSp-game.state.sp);game.state.sp+=n;toast(`Restored ${n} SP.`)}else{toast('Rations are best used during a rest.');return}it.count--;if(it.count===0)game.state.inventory.splice(i,1);persist();document.querySelector('.modal-backdrop')?.remove();modalInventory();render()}
function choose(i){const s=game.state;if(!s)return;const sc=scene();const choice=sc.choices[i];if(!choice)return;s.decisions.push({floor:s.floor,scene:s.storyKey,choice});if(s.storyKey==='opening'){if(i===0){s.relationships.Klein+=1;s.storyKey='afterIntro';s.journal.push('After Kayaba’s announcement, I pushed through the crowd toward the gate.');}else if(i===1){s.relationships.Asuna+=1;s.storyKey='afterIntro';s.journal.push('I searched for the red-haired player, but the crowd swallowed her.');}else if(i===2){s.relationships.Kirito+=1;s.storyKey='afterIntro';s.journal.push('I found the quiet black-haired player, Kirito, already mapping a route to the gate.');}else{s.relationships.Klein+=1;s.storyKey='afterIntro';s.hp=Math.min(s.maxHp,s.hp+4);s.journal.push('I helped calm a panicked player in the plaza.');}}
else if(s.storyKey==='afterIntro'){if(i===0){s.relationships.Klein+=2;s.party=['Klein'];s.journal.push('I joined Klein’s small group for the first trip outside.');}else if(i===1){s.relationships.Kirito+=1;s.journal.push('I headed out alone, following Kirito’s example.');}else if(i===2){s.storyKey='town';s.journal.push('I checked the item stalls before venturing out.');render();return;}else{s.relationships.Asuna+=1;s.journal.push('I asked about the red-haired player. No one knew her name yet.');}}else if(s.storyKey==='firstField'){if(i===0){startCombat('Grey Wolf',1);return}else if(i===1){s.journal.push('I studied the Grey Wolf’s pattern before it could close in.');s.dex+=1;startCombat('Grey Wolf',1);return}else{s.storyKey='town';s.journal.push('I chose not to risk a fight before I was ready.');render();return}}else if(s.storyKey==='afterBattle'){if(i===0){s.storyKey='town';s.journal.push('I returned to town to recover and resupply.');}else if(i===1){s.relationships.Asuna+=1;s.journal.push('I followed the distant frontline party and spotted Asuna among them.');s.storyKey='questDone';}else{s.storyKey='questDone';s.journal.push('I searched the nearby ruins for a hidden cache.');if(Math.random()<.65){s.col+=25;s.inventory.push({name:'Old Coin',type:'misc',count:1,info:'A tarnished coin from a forgotten floor-1 ruin.'});s.journal.push('I found an old coin worth 25 Col.');}}}else if(s.storyKey==='town'){if(i===0){openBlacksmith();return}else if(i===1){s.hp=s.maxHp;s.sp=s.maxSp;s.storyKey='questDone';s.journal.push('I rested at the inn and recovered fully.');}else if(i===2){offerQuest();return}else{s.storyKey='firstField';s.journal.push('I left town and returned to the outer field.');}}else if(s.storyKey==='questDone'){if(i===0){s.storyKey='town';}else if(i===1){s.hp=Math.min(s.maxHp,s.hp+18);s.sp=Math.min(s.maxSp,s.sp+10);s.storyKey='firstField';}else if(i===2){offerQuest();return}else{s.storyKey='firstField';}}else if(s.storyKey==='floorClear'){if(i===0){advanceFloor();return}else if(i===1){s.storyKey='town';s.location=floors[s.floor-1][0];}else if(i===2){s.party=['Frontier Scout','Shield Bearer'];s.journal.push('I found a frontline party recruiting at the gate.');s.storyKey='questDone';}else{startCombat(floors[s.floor-1][3],s.floor);return}}else if(s.storyKey==='bossAfter'){if(i===0){advanceFloor();return}else if(i===1){s.hp=Math.min(s.maxHp,s.hp+20);s.storyKey='floorClear';s.journal.push('I stayed behind to help wounded players.');}else{s.relationships.Kirito+=1;s.relationships.Asuna+=1;s.storyKey='floorClear';s.journal.push('I spoke with Kirito and Asuna; they thanked me for my help.');}}else{s.storyKey='floorClear'}persist();render()}
function customAction(){const input=document.getElementById('customAction');const action=input?.value.trim();if(!action)return;const s=game.state;s.decisions.push({floor:s.floor,scene:s.storyKey,choice:`Custom: ${action}`});s.journal.push(`I chose to ${action.toLowerCase()}.`);let lower=action.toLowerCase();if(/status|inventory|quest|journal|save/.test(lower)){const cmd=['status','inventory','quest','journal','save'].find(x=>lower.includes(x));command(cmd.toUpperCase());return}if(s.storyKey==='opening'){s.relationships.Klein+=1;s.storyKey='afterIntro'}else if(s.storyKey==='afterIntro'){if(/town|shop|buy|inn|rest/.test(lower))s.storyKey='town';else{s.storyKey='firstField';}}else if(s.storyKey==='firstField'){if(/retreat|run|leave|avoid/.test(lower)){s.storyKey='town'}else{startCombat('Grey Wolf',1);return}}else if(s.storyKey==='town'){if(/rest|sleep/.test(lower)){s.hp=s.maxHp;s.sp=s.maxSp;s.storyKey='questDone'}else if(/blacksmith|upgrade|forge/.test(lower)){openBlacksmith();return}else{s.storyKey='firstField'}}else if(s.storyKey==='afterBattle'){s.storyKey=/town|rest|heal/.test(lower)?'town':'questDone'}else if(s.storyKey==='floorClear'){if(/next|advance|gate/.test(lower)){advanceFloor();return}else if(/town/.test(lower)){s.storyKey='town'}else{startCombat(floors[s.floor-1][3],s.floor);return}}else{s.storyKey='floorClear'}persist();render()}
function openBlacksmith(){const s=game.state;const price=75+s.floor*12;modal('Blacksmith',`<p>“Good steel can’t save a careless fighter,” the smith says, turning your ${esc(s.weapon)} in the light. “But it can buy you a little margin.”</p><div class="item-row"><div><div class="item-name">Hone ${esc(s.weapon)}</div><div class="item-info">+2 weapon damage · Price ${price} Col</div></div><button class="item-action" onclick="upgradeWeapon()">UPGRADE</button></div><div class="item-row"><div><div class="item-name">Reinforce tunic</div><div class="item-info">+2 DEF · Price ${price} Col</div></div><button class="item-action" onclick="upgradeArmor()">UPGRADE</button></div><p class="subtle">Col on hand: ${s.col}</p>`)}
function upgradeWeapon(){const p=75+game.state.floor*12;if(game.state.col<p){toast('Not enough Col.');return}game.state.col-=p;game.state.weaponDamage+=2;game.state.journal.push(`Blacksmith upgraded my ${game.state.weapon}.`);persist();document.querySelector('.modal-backdrop')?.remove();render();toast('Weapon upgraded: +2 damage.')}
function upgradeArmor(){const p=75+game.state.floor*12;if(game.state.col<p){toast('Not enough Col.');return}game.state.col-=p;game.state.armorDef+=2;game.state.def+=2;game.state.journal.push('Blacksmith reinforced my armor.');persist();document.querySelector('.modal-backdrop')?.remove();render();toast('Armor reinforced: +2 DEF.')}
