function gainLevels(){const s=game.state;while(s.exp>=s.nextExp){s.exp-=s.nextExp;s.level++;s.nextExp=Math.round(s.nextExp*1.35);s.maxHp+=12;s.maxSp+=4;s.hp=s.maxHp;s.sp=s.maxSp;s.str+=2;s.agi+=1;s.vit+=1;s.def+=1;s.journal.push(`Reached Level ${s.level}.`);}}
function startCombat(name,floor){const s=game.state;const boss=name==='Ape King'||name==='Illfang the Kobold Lord'||name==='The Warden'||name==='The Drowned King'||name==='Frostfang'||name==='Thorn Witch'||name==='The Sand Tyrant';const base=18+floor*8;game.combat={name,level:floor,boss,phase:1,hp:boss?base*4:base,maxHp:boss?base*4:base,attack:boss?8+floor*2:4+floor*1.5,turn:0,telegraph:'watching you',log:`${name} steps into range. The battle begins.`};game.mode='combat';s.storyKey='combat';render()}
function renderCombat(){const c=game.combat,s=game.state;app.innerHTML=`${topbar()}<div class="eyebrow">FLOOR ${s.floor} · FIELD ENCOUNTER</div><h1 class="title" style="font-size:clamp(28px,4vw,40px);margin-top:7px">The fight is real.</h1><p class="subtitle">Read the enemy’s tell before you commit. Strong attacks cost SP; a well-timed defense can create an opening.</p><div class="layout"><section class="main-col"><div class="panel"><div class="panel-heading">COMBAT ENCOUNTER <b>${c.boss?'BOSS · PHASE '+c.phase:'DANGER'}</b></div><div class="combat-status"><div><div class="bar-label"><span>YOUR HP</span><span>${s.hp} / ${s.maxHp}</span></div><div class="bar"><span style="width:${100*s.hp/s.maxHp}%"></span></div><div class="bar-label"><span>YOUR SP</span><span>${s.sp} / ${s.maxSp}</span></div><div class="bar sp"><span style="width:${100*s.sp/s.maxSp}%"></span></div></div><div><div class="bar-label"><span>${esc(c.name.toUpperCase())} HP</span><span>${Math.max(0,c.hp)} / ${c.maxHp}</span></div><div class="enemy-bar"><span style="width:${Math.max(0,100*c.hp/c.maxHp)}%"></span></div><div class="subtle" style="margin-top:8px">${c.boss?`MULTI-PHASE BOSS · PHASE ${c.phase}`:'FIELD MONSTER'} · TURN ${c.turn+1}</div></div></div><div class="enemy-card"><div class="enemy-name">${esc(c.name)}</div><div class="enemy-desc">${enemyDescription(c.name)}<br><b style="color:#e19484">Tell:</b> ${esc(c.telegraph)}</div></div><div class="combat-actions"><button class="action-btn primary" onclick="combatAction('attack')">ATTACK <span class="subtle">No cost</span></button><button class="action-btn" onclick="combatAction('sword')" ${s.sp<10?'disabled':''}>SWORD SKILL <span class="subtle">10 SP</span></button><button class="action-btn" onclick="combatAction('dodge')">DODGE <span class="subtle">evade</span></button><button class="action-btn" onclick="combatAction('parry')">PARRY <span class="subtle">timing</span></button><button class="action-btn" onclick="combatAction('guard')">GUARD <span class="subtle">reduce dmg</span></button><button class="action-btn" onclick="combatAction('counter')">COUNTER <span class="subtle">read tell</span></button><button class="action-btn" onclick="combatAction('special')" ${s.sp<18?'disabled':''}>SPECIAL <span class="subtle">18 SP</span></button><button class="action-btn" onclick="command('INVENTORY')">ITEM <span class="subtle">use potion</span></button><button class="action-btn" onclick="fleeCombat()">RETREAT <span class="subtle">surrender ground</span></button></div><div class="combat-log">${esc(c.log)}</div>${s.hp<=0?`<div class="dead-overlay">HP has reached zero. The world blurs at its edges. There is no respawn screen. Your save remains at this encounter; choose LOAD to return to the last saved state, or accept a costly recovery event to continue the AU.</div><button class="secondary-btn" style="margin-top:10px" onclick="recoverFromDeath()">ACCEPT AU RECOVERY (LOSE COL + GEAR DURABILITY)</button>`:''}</div><div class="panel"><div class="panel-heading">TACTICAL NOTE <b>READ THE TELL</b></div><p class="side-copy">A lunging enemy can be dodged; a committed attack can be parried. Guard is dependable but slow. Counters reward a correct read and punish a wrong one.</p><div class="command-row"><button class="command-btn" onclick="command('STATUS')">STATUS</button><button class="command-btn" onclick="command('SAVE')">SAVE</button></div></div></section><aside class="side-col"><div class="panel side-panel"><div class="panel-heading">PLAYER STATUS <b>LV ${s.level}</b></div>${statusBars()}<div class="stat-list"><div class="stat-line"><span>WEAPON</span><b>${esc(s.weapon)} · +${s.weaponDamage}</b></div><div class="stat-line"><span>DEFENCE</span><b>${s.def}</b></div><div class="stat-line"><span>PROFICIENCY</span><b>${s.proficiency}%</b></div><div class="stat-line"><span>SKILL MASTERY</span><b>${s.mastery}%</b></div></div></div><div class="panel side-panel"><div class="panel-heading">PARTY <b>${s.party.length?'READY':'SOLO'}</b></div><p class="side-copy">${s.party.length?`Fighting alongside ${esc(s.party.join(', '))}. Party members provide modest support.`:'You are fighting alone. Party opportunities appear through story choices and town missions.'}</p></div></aside></div>`}
function enemyDescription(n){if(n==='Grey Wolf')return 'A pack hunter testing for a stumble before it commits to a lunge.';if(n==='Kobold Lord'||n==='Illfang the Kobold Lord')return 'A trained commander with a heavy axe and a second phase hidden behind its armor.';if(n==='Ape King')return 'A huge beast that telegraphs wide sweeps before striking the ground.';if(n==='The Warden')return 'An armored sentinel. Its shield makes reckless attacks dangerous.';return 'A hostile creature with a shifting rhythm and a powerful committed strike.'}
function combatAction(action){const s=game.state,c=game.combat;if(!c||s.hp<=0)return;const tell=c.telegraph.toLowerCase();let msg='';let enemyHit=0;let playerDamage=0;const style=s.profile.style;const crit=Math.random();if(action==='attack'){playerDamage=Math.max(2,Math.round(s.weaponDamage+s.str*.45+Math.random()*5));if(crit<.12){playerDamage=Math.round(playerDamage*1.5);msg=`A clean opening—your strike deals ${playerDamage} damage.`}else msg=`You strike for ${playerDamage} damage.`;c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+2)}else if(action==='sword'){if(s.sp<10){toast('Not enough SP.');return}s.sp-=10;let skill=s.proficiency>=25?'Vorpal Strike':'Sonic Leap';playerDamage=Math.round(s.weaponDamage+s.str*.65+8+Math.random()*5);if(crit<.20)playerDamage=Math.round(playerDamage*1.25);c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+3);s.mastery=Math.min(100,s.mastery+2);msg=`${skill}! The Sword Skill connects for ${playerDamage} damage.`}else if(action==='special'){if(s.sp<18){toast('Not enough SP.');return}if(s.level<10||s.mastery<35){toast('Special attack requires Level 10 and 35 Skill Mastery.');return}s.sp-=18;playerDamage=Math.round(s.weaponDamage+s.str+18+Math.random()*10);c.hp-=playerDamage;s.mastery=Math.min(100,s.mastery+4);msg=`Starburst Stream unleashes a controlled sequence for ${playerDamage} damage. The technique drains your SP.`}else if(action==='dodge'){if(tell.includes('swing')||tell.includes('lunge')||tell.includes('strike')||tell.includes('ground')){enemyHit=0;msg='You evade the committed attack by a hair, keeping your footing.';s.agi+=0}else{enemyHit=Math.max(1,Math.round(c.attack*.55));msg='You dodge too early. The enemy clips you as you move.'}}else if(action==='parry'){if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung')){enemyHit=0;playerDamage=Math.round(s.weaponDamage+3+s.dex*.45);c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+2);msg=`A precise parry turns the attack aside. Your counter deals ${playerDamage} damage.`}else{enemyHit=Math.round(c.attack*.85);msg='The enemy feints. Your parry comes early and leaves you exposed.'}}else if(action==='guard'){enemyHit=Math.max(1,Math.round(c.attack*.34-s.def*.2));msg=`You brace behind your ${esc(s.weapon.toLowerCase())} and absorb most of the impact (${enemyHit} damage).`;s.sp=Math.min(s.maxSp,s.sp+2)}else if(action==='counter'){if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung')){enemyHit=0;playerDamage=Math.round(s.weaponDamage+6+s.dex*.55);c.hp-=playerDamage;msg=`You read the tell and counter the committed move for ${playerDamage} damage.`}else{enemyHit=Math.round(c.attack*1.15);msg='The enemy changes its rhythm. Your counter misses; you take a hit.'}}if(action==='attack'||action==='sword'||action==='special'){if(c.hp>0){enemyHit=Math.max(1,Math.round(c.attack-s.def*.35));if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung'))enemyHit+=Math.round(c.attack*.35);msg+=` ${c.name} follows through; you take ${enemyHit} damage.`}}s.hp=Math.max(0,s.hp-enemyHit);c.turn++;if(c.hp>0){if(c.boss&&c.hp<=c.maxHp*.5&&c.phase===1){c.phase=2;c.attack=Math.round(c.attack*1.35);c.telegraph='winding up a heavy, wide sweep';msg+=` Phase two: ${c.name} breaks its stance and attacks faster!`;}else{const tells=['watching you','winding up a heavy, wide sweep','feinting, then preparing a lunge','drawing back for a committed strike'];c.telegraph=tells[(c.turn+Math.floor(Math.random()*tells.length))%tells.length];}c.log=msg}else{c.hp=0;winCombat(msg)}if(s.hp<=0){c.log=msg+' Your HP has reached zero.';s.flags.death=true;s.journal.push(`I fell in battle against ${c.name}.`)}persist();render()}
function winCombat(msg){const s=game.state,c=game.combat;const boss=c.boss;let exp=(boss?45:18)+s.floor*8;let col=(boss?90:22)+s.floor*8;s.exp+=exp;s.col+=col;s.hp=Math.max(1,s.hp);s.sp=Math.min(s.maxSp,s.sp+5);s.battleLog=`${c.name} defeated. +${exp} EXP · +${col} Col.`;s.journal.push(`Defeated ${c.name} on Floor ${s.floor}.`);if(s.storyKey==='combat'){if(s.floor===1&&!boss){completeQuest();s.storyKey='afterBattle'}else if(boss){s.flags.bosses.push(s.floor);s.storyKey='bossAfter'}else{s.storyKey='floorClear'}}gainLevels();c.log=`${msg} ${c.name} is defeated. +${exp} EXP and +${col} Col.`;game.mode='story';game.combat=null;persist();render();toast(`Victory · +${exp} EXP · +${col} Col`)}
function fleeCombat(){const s=game.state;const c=game.combat;if(Math.random()<.78){game.mode='story';game.combat=null;s.storyKey='town';s.hp=Math.max(1,s.hp-3);s.journal.push(`I retreated from ${c.name} and returned to safety.`);persist();render();toast('Retreated to the nearest safe zone.')}else{const dmg=Math.max(1,Math.round(c.attack*.45));s.hp=Math.max(0,s.hp-dmg);c.log=`You cannot break away! You take ${dmg} damage.`;persist();render()}}
