function customAction(){const input=document.getElementById('customAction');const action=input?.value.trim();if(!action)return;const s=game.state;s.decisions.push({floor:s.floor,scene:s.storyKey,choice:`Custom: ${action}`});s.journal.push(`I chose to ${action.toLowerCase()}.`);let lower=action.toLowerCase();if(/status|inventory|quest|journal|save/.test(lower)){const cmd=['status','inventory','quest','journal','save'].find(x=>lower.includes(x));command(cmd.toUpperCase());return}if(s.storyKey==='opening'){s.relationships.Klein+=1;s.storyKey='afterIntro'}else if(s.storyKey==='afterIntro'){if(/town|shop|buy|inn|rest/.test(lower))s.storyKey='town';else{s.storyKey='firstField';}}else if(s.storyKey==='firstField'){if(/retreat|run|leave|avoid/.test(lower)){s.storyKey='town'}else{startCombat('Grey Wolf',1);return}}else if(s.storyKey==='town'){if(/rest|sleep/.test(lower)){s.hp=s.maxHp;s.sp=s.maxSp;s.storyKey='questDone'}else if(/blacksmith|upgrade|forge/.test(lower)){openBlacksmith();return}else{s.storyKey='firstField'}}else if(s.storyKey==='afterBattle'){s.storyKey=/town|rest|heal/.test(lower)?'town':'questDone'}else if(s.storyKey==='floorClear'){if(/next|advance|gate/.test(lower)){advanceFloor();return}else if(/town/.test(lower)){s.storyKey='town'}else if(/boss|labyrinth/.test(lower)){startCombat(floors[s.floor-1][4],s.floor);return}else{startCombat(floors[s.floor-1][3],s.floor);return}}else{s.storyKey='floorClear'}persist();render()}
function openBlacksmith(){const s=game.state;const price=75+s.floor*12;modal('Blacksmith',`<p>“Good steel can’t save a careless fighter,” the smith says, turning your ${esc(s.weapon)} in the light. “But it can buy you a little margin.”</p><div class="item-row"><div><div class="item-name">Hone ${esc(s.weapon)}</div><div class="item-info">+2 weapon damage · Price ${price} Col</div></div><button class="item-action" onclick="upgradeWeapon()">UPGRADE</button></div><div class="item-row"><div><div class="item-name">Reinforce tunic</div><div class="item-info">+2 DEF · Price ${price} Col</div></div><button class="item-action" onclick="upgradeArmor()">UPGRADE</button></div><p class="subtle">Col on hand: ${s.col}</p>`)}
