function completeQuest(){const s=game.state;const q=s.quests.find(x=>x.state==='Active');if(q){q.state='Complete';let exp=20+s.floor*5;let col=35+s.floor*10;s.exp+=exp;s.col+=col;s.journal.push(`Quest complete: ${q.title}. Reward: ${exp} EXP and ${col} Col.`);gainLevels();}s.flags.monsterDefeated=(s.flags.monsterDefeated||0)+1;if(s.flags.monsterDefeated>=1){const main=s.quests.find(x=>x.id==='first-steps');if(main&&main.state==='Active'){main.state='Complete';s.exp+=25;s.col+=40;s.journal.push('Quest complete: Aincrad: First Steps.');gainLevels()}}}
