69:function combatAction(action){const s=game.state,c=game.combat;if(!c||s.hp<=0)return;const tell=c.telegraph.toLowerCase();let msg='';let enemyHit=0;let playerDamage=0;const style=s.profile.style;const crit=Math.random();if(action==='attack'){playerDamage=Math.max(2,Math.round(s.weaponDamage+s.str*.45+Math.random()*5));if(crit<.12){playerDamage=Math.round(playerDamage*1.5);msg=`A clean opening—your strike deals ${playerDamage} damage.`}else msg=`You strike for ${playerDamage} damage.`;c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+2)}else if(action==='sword'){if(s.sp<10){toast('Not enough SP.');return}s.sp-=10;let skill=s.proficiency>=25?'Vorpal Strike':'Sonic Leap';playerDamage=Math.round(s.weaponDamage+s.str*.65+8+Math.random()*5);if(crit<.20)playerDamage=Math.round(playerDamage*1.25);c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+3);s.mastery=Math.min(100,s.mastery+2);msg=`${skill}! The Sword Skill connects for ${playerDamage} damage.`}else if(action==='special'){if(s.sp<18){toast('Not enough SP.');return}if(s.level<10||s.mastery<35){toast('Special attack requires Level 10 and 35 Skill Mastery.');return}s.sp-=18;playerDamage=Math.round(s.weaponDamage+s.str+18+Math.random()*10);c.hp-=playerDamage;s.mastery=Math.min(100,s.mastery+4);msg=`Starburst Stream unleashes a controlled sequence for ${playerDamage} damage. The technique drains your SP.`}else if(action==='dodge'){if(tell.includes('swing')||tell.includes('lunge')||tell.includes('strike')||tell.includes('ground')){enemyHit=0;msg='You evade the committed attack by a hair, keeping your footing.';s.agi+=0}else{enemyHit=Math.max(1,Math.round(c.attack*.55));msg='You dodge too early. The enemy clips you as you move.'}}else if(action==='parry'){if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung')){enemyHit=0;playerDamage=Math.round(s.weaponDamage+3+s.dex*.45);c.hp-=playerDamage;s.proficiency=Math.min(100,s.proficiency+2);msg=`A precise parry turns the attack aside. Your counter deals ${playerDamage} damage.`}else{enemyHit=Math.round(c.attack*.85);msg='The enemy feints. Your parry comes early and leaves you exposed.'}}else if(action==='guard'){enemyHit=Math.max(1,Math.round(c.attack*.34-s.def*.2));msg=`You brace behind your ${esc(s.weapon.toLowerCase())} and absorb most of the impact (${enemyHit} damage).`;s.sp=Math.min(s.maxSp,s.sp+2)}else if(action==='counter'){if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung')){enemyHit=0;playerDamage=Math.round(s.weaponDamage+6+s.dex*.55);c.hp-=playerDamage;msg=`You read the tell and counter the committed move for ${playerDamage} damage.`}else{enemyHit=Math.round(c.attack*1.15);msg='The enemy changes its rhythm. Your counter misses; you take a hit.'}}if(action==='attack'||action==='sword'||action==='special'){if(c.hp>0){enemyHit=Math.max(1,Math.round(c.attack-s.def*.35));if(tell.includes('committed')||tell.includes('wide')||tell.includes('heavy')||tell.includes('lung'))enemyHit+=Math.round(c.attack*.35);msg+=` ${c.name} follows through; you take ${enemyHit} damage.`}}s.hp=Math.max(0,s.hp-enemyHit);c.turn++;if(c.hp>0){if(c.boss&&c.hp<=c.maxHp*.5&&c.phase===1){c.phase=2;c.attack=Math.round(c.attack*1.35);c.telegraph='winding up a heavy, wide sweep';msg+=` Phase two: ${c.name} breaks its stance and attacks faster!`;}else{const tells=['watching you','winding up a heavy, wide sweep','feinting, then preparing a lunge','drawing back for a committed strike'];c.telegraph=tells[(c.turn+Math.floor(Math.random()*tells.length))%tells.length];}c.log=msg}else{c.hp=0;winCombat(msg)}if(s.hp<=0){c.log=msg+' Your HP has reached zero.';s.flags.death=true;s.journal.push(`I fell in battle against ${c.name}.`)}persist();render()}
70:function winCombat(msg){const s=game.state,c=game.combat;const boss=c.boss;let exp=(boss?45:18)+s.floor*8;let col=(boss?90:22)+s.floor*8;s.exp+=exp;s.col+=col;s.hp=Math.max(1,s.hp);s.sp=Math.min(s.maxSp,s.sp+5);s.battleLog=`${c.name} defeated. +${exp} EXP · +${col} Col.`;s.journal.push(`Defeated ${c.name} on Floor ${s.floor}.`);if(s.storyKey==='combat'){if(s.floor===1&&!boss){completeQuest();s.storyKey='afterBattle'}else if(boss){s.flags.bosses.push(s.floor);const q=s.quests.find(x=>x.id===`boss-${s.floor}`&&x.state==='Active');if(q){q.state='Complete';const bonus=50+s.floor*4;s.exp+=bonus;s.col+=120+s.floor*8;s.journal.push(`Boss quest complete: ${q.title}.`)}s.storyKey=s.floor===100?'ending':'bossAfter'}else{s.storyKey='floorClear'}}gainLevels();c.log=`${msg} ${c.name} is defeated. +${exp} EXP and +${col} Col.`;game.mode='story';game.combat=null;persist();render();toast(`Victory · +${exp} EXP · +${col} Col`)}
