24: function renderCreation(){app.innerHTML=`${topbar()}<div class="eyebrow">Aincrad • November 6, 2022</div><h1 class="title">Your story begins<br>at the edge of a blade.</h1><p class="subtitle">Aincrad is a world of a hundred floors, and every choice leaves a mark. First, tell us who you are. You begin as an ordinary player—your strength will be earned.</p><div class="layout"><section class="main-col"><div class="panel"><div class="panel-heading"><span>Character creation</span><span><b>0${game.step+1}</b> / 03</span></div><div class="step-progress">${[0,1,2].map(i=>`<span class="step-dot ${i<=game.step?'active':''}"></span>`).join('')}<span class="step-name">${['IDENTITY','TEMPERAMENT','LOADOUT'][game.step]}</span></div>${creationStep()}</div><div class="panel"><div class="panel-heading">Before you enter <b>NOTICE</b></div><div class="intro-note"><span class="note-icon">✧</span><span>SAO is a persistent challenge. Choices change your resources, relationships, and opportunities. Your game saves in this browser; use <b>LOAD</b> to continue later.</span></div></div></section><aside class="side-col"><div class="panel side-panel"><div class="eyebrow">SYSTEM NOTICE</div><h2 class="side-title">The world is waiting.</h2><p class="side-copy">On launch day, ten thousand players will enter the floating castle. No one expects the rules to change.</p><div class="stat-list"><div class="stat-line"><span>STARTING FLOOR</span><b>01 — Aincrad</b></div><div class="stat-line"><span>STARTING LEVEL</span><b>01 — Beginner</b></div><div class="stat-line"><span>DIFFICULTY</span><b>Adaptive / Strategic</b></div><div class="stat-line"><span>STORY ROUTE</span><b>AU · Floors 1–100</b></div></div><div class="divider"></div><button class="secondary-btn" style="width:100%" onclick="command('LOAD')">LOAD EXISTING SAVE</button></div><div class="panel side-panel"><div class="panel-heading">How to play <b>GUIDE</b></div><p class="side-copy">Read the scene, then choose an action or type your own. Battles... (line truncated to 2000 chars)
25: function creationStep(){const d=game.draft;if(game.step===0)return `<h2 class="section-title">Who are you?</h2><p class="side-copy">A new face in a crowded starting city. Your name and look are yours to decide.</p><div class="field-grid" style="margin-top:17px"><div class="field"><label for="cname">Player name *</label><input id="cname" maxlength="24" placeholder="Name" value="${esc(d.name)}"></div><div class="field"><label for="age">Age</label><input id="age" type="number" min="13" max="99" value="${esc(d.age)}"></div><div class="field"><label for="gender">Gender</label><select id="gender">${['Unspecified','Woman','Man','Non-binary'].map(x=>`<option ${d.gender===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="appearance">Appearance</label><input id="appearance" maxlength="90" placeholder="A detail people notice…" value="${esc(d.appearance)}"></div></div><div class="btn-row"><button class="primary-btn" onclick="nextCreation()">CONTINUE　→</button></div>`;
26: if(game.step===1)return `<h2 class="section-title">What drives you?</h2><p class="side-copy">Your past informs your first instincts, but it does not decide who you become.</p><div class="field-grid" style="margin-top:17px"><div class="field"><label>Personality</label><select id="personality">${['Cautiously curious','Quietly determined','Warm and sociable','Wry and observant','Restless and bold','Thoughtful and reserved'].map(x=>`<option ${d.personality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Background</label><select id="background">${['A first-day player','A careful beta tester','A solo-minded wanderer','A longtime gamer','A newcomer to games','A friend of a friend'].map(x=>`<option ${d.background===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>One thing you hope to find</label><input id="hope" maxlength="80" placeholder="A reason to keep going…" value="${esc(d.hope||'')}"></div></div><div class="btn-row"><button class="secondary-btn" onclick="prevCreation()">← BACK</button><button class="primary-btn" onclick="nextCreation()">CONTINUE　→</button></div>`;
27: return `<h2 class="section-title">Choose your first weapon.</h2><p class="side-copy">Every weapon has a different rhythm. You are still a beginner: skill comes from practice, not from a menu.</p><div class="field-grid" style="margin-top:17px"><div class="field full"><label>Weapon</label><select id="weapon">${['One-handed sword','Rapier','Dagger','Two-handed axe','Spear','Mace'].map(x=>`<option ${d.weapon===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Combat style</label><select id="style">${['Balanced','Quick and evasive','Patient and defensive','Direct and forceful','Precise and tactical'].map(x=>`<option ${d.style===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="intro-note"><span class="note-icon">⚔</span><span><b>${esc(d.weapon)}</b> • ${esc(d.style)}<br>You begin with starter gear, 100 HP, and no mastered Sword Skills.</span></div><div class="btn-row"><button class="secondary-btn" onclick="prevCreation()">← BACK</button><button class="primary-btn" onclick="beginGame()">ENTER AINCRAD　✦</button></div>`}
