42: function townScene(){let loc=floors[game.state.floor-1][0];return {title:`${loc.toUpperCase()} · SAFE ZONE`,label:`FLOOR ${game.state.floor} · TOWN`,text:`The safety of town is mostly an illusion, but the system’s blue boundary is a comfort I did not expect to need. Traders call out prices beneath canvas awnings. The blacksmith’s hammer rings steadily. Adventurers compare maps and keep one eye on the distant labyrinth.\n\n${game.state.floor===1?'At a table near the fountain, Klein waves when he spots me. “You made it back! Not bad for day one.”':'The town has grown familiar, though the faces change with every floor. A notice board carries local jobs, and the inn offers a place to restore strength.'} I can spend Col on supplies, improve my gear, take a small job, or get back to the field.`,choices:['Visit the blacksmith. Improve my weapon or armor.','Rest at the inn and recover HP and SP.','Take a local side quest from the notice board.','Leave town and continue exploring.']}}
43: function floorScene(){const s=game.state;const bossFloor=s.floor%5===0||s.floor===100;const choices=['Explore the frontier cautiously.','Find the town and gather information.','Look for a party forming near the gate.','Go straight to the labyrinth entrance (dangerous).'];if(bossFloor)choices.push(`Challenge ${floors[s.floor-1][4]} (boss raid).`);return {title:`FLOOR ${s.floor} · ${floors[s.floor-1][1].toUpperCase()}`,label:`THE FRONTIER · FLOOR ${s.floor}`,text:`The gate opens onto a new sky. Floor ${s.floor} spreads out in a landscape unlike the last: ${floors[s.floor-1][1].toLowerCase()}, with a town called ${floors[s.floor-1][0]} marked on the map. The labyrinth entrance rises beyond the wilderness, its stonework visible through the haze.\n\nThe first monsters here are stronger than the ones I faced before. I am not expected to conquer the floor alone, and no one is forcing me to. The frontier group needs scouts, crafters, and people who know when to retreat. I check my supplies and choose my next step.`,choices}}
44: function genericScene(){return {title:'THE ROAD AHEAD',label:`FLOOR ${game.state.floor} · ${game.state.location.toUpperCase()}`,text:'The wind moves through the grass. Somewhere ahead, the next piece of Aincrad waits, shaped by the decisions that brought me here. I take a breath and choose my direction.',choices:['Continue exploring.','Return to town.','Check my status and prepare.']}}
45: function renderStory(){const sc=scene();app.innerHTML=`${topbar()}<div class="story-head"><div><div class="event-label">${sc.label}</div><h1 class="title" style="font-size:clamp(28px,4vw,40px);margin:7px 0 0">${sc.title}</h1></div><span class="tag">${game.state.location}</span></div><div class="layout"><section class="main-col"><div class="panel"><div class="story-copy">${sc.text.split('\n\n').map(p=>`<p>${p}</p>`).join('')}</div><div class="choice-list">${sc.choices.map((c,i)=>`<button class="story-choice" onclick="choose(${i})"><span class="choice-num">0${i+1}</span><span>${c}</span></button>`).join('')}</div><div class="free-action"><input id="customAction" placeholder="Or describe your own action…" maxlength="140" onkeydown="if(event.key==='Enter')customAction()"><button onclick="customAction()">ACT ↗</button></div><div class="divider"></div><div class="command-row">${['STATUS','INVENTORY','QUEST','JOURNAL','SAVE'].map(c=>`<button class="command-btn" onclick="command('${c}')">${c}</button>`).join('')}</div></div>${game.state.battleLog?`<div class="panel"><div class="panel-heading">Latest report <b>FIELD LOG</b></div><div class="log">${esc(game.state.battleLog)}</div></div>`:''}</section><aside class="side-col"><div class="panel side-panel"><div class="panel-heading">PLAYER STATUS <b>LV ${game.state.level}</b></div>${statusBars()}<div class="mini-grid">${[['STR',game.state.str],['AGI',game.state.agi],['VIT',game.state.vit],['DEX',game.state.dex],['DEF',game.state.def],['COL',game.state.col]].map(x=>`<div class="mini-stat">${x[0]}<b>${x[1]}</b></div>`).join('')}</div><div class="stat-list"><div class="stat-line"><span>WEAPON</span><b>${esc(game.state.weapon)}</b></div><div class="stat-line"><span>PROFICIENCY</span><b>${game.state.proficiency}%</b></div><div class="stat-line"><span>EXP</span><b>${game.state.exp} / ${game.state.nextExp}</b></div></div></div><div class="panel side-panel"><div class="panel-heading">CURRENT QUEST <b>${game.state.quests.some(q=>q.state=... (line truncated to 2000 chars)
46: function statusBars(){const s=game.state;return `<div class="bar-label"><span>HP</span><span>${s.hp} / ${s.maxHp}</span></div><div class="bar"><span style="width:${100*s.hp/s.maxHp}%"></span></div><div class="bar-label"><span>SP</span><span>${s.sp} / ${s.maxSp}</span></div><div class="bar sp"><span style="width:${100*s.sp/s.maxSp}%"></span></div>`}
47: function persist(){if(game.state){localStorage.setItem(SAVE_KEY,JSON.stringify({state:game.state,mode:'story'}))}}
