44: function genericScene(){return {title:'THE ROAD AHEAD',label:`FLOOR ${game.state.floor} · ${game.state.location.toUpperCase()}`,text:'The wind moves through the grass. Somewhere ahead, the next piece of Aincrad waits, shaped by the decisions that brought me here. I take a breath and choose my direction.',choices:['Continue exploring.','Return to town.','Check my status and prepare.']}}
