46: function statusBars(){const s=game.state;return `<div class="bar-label"><span>HP</span><span>${s.hp} / ${s.maxHp}</span></div><div class="bar"><span style="width:${100*s.hp/s.maxHp}%"></span></div><div class="bar-label"><span>SP</span><span>${s.sp} / ${s.maxSp}</span></div><div class="bar sp"><span style="width:${100*s.sp/s.maxSp}%"></span></div>`}
