 function prevCreation(){collectStep();game.step=Math.max(0,game.step-1);render()}
 function beginGame(){collectStep();const name=game.draft.name.trim();if(!name){game.step=0;render();toast('Choose a player name first.');return}const weaponStats={'One-handed sword':{str:5,agi:5,damage:7},Rapier:{str:4,agi:7,damage:6},Dagger:{str:4,agi:8,damage:5},'Two-handed axe':{str:8,agi:3,damage:9},Spear:{str:6,agi:5,damage:7},Mace:{str:7,agi:4,damage:8}};const w=weaponStats[game.draft.weapon];game.state={name,profile:{...game.draft},floor:1,level:1,exp:0,nextExp:40,hp:100,maxHp:100,sp:35,maxSp:35,str:10+w.str,agi:10+w.agi,vit:10,dex:10,def:5,proficiency:0,mastery:0,weaponDamage:w.damage,weapon:game.draft.weapon,armor:'Traveler’s Tunic',armorDef:2,inventory:[{name:'Healing Potion',type:'consumable',count:3,info:'Restores 35 HP.'},{name:'Minor SP Tonic',type:'consumable',count:2,info:'Restores 18 SP.'},{name:'Field Rations',type:'consumable',count:2,info:'A simple meal for the road.'}],col:120,quests:[{id:'first-steps',title:'Aincrad: First Steps',desc:'Reach the outer field and learn to survive. Defeat one monster.',state:'Active',reward:'25 EXP · 40 Col'}],journal:['November 6, 2022 — I logged into Sword Art Online for launch day.','The mirror event stripped away my avatar disguise. I am now trapped in my own face.'],relationships:{'Kirito':0,'Asuna':0,'Klein':0,'Agil':0},guild:null,party:[],flags:{intro:true,monsterDefeated:0,seenFloor:{},bosses:[],death:false},turn:0,location:'Starting City',storyKey:'opening',event:'THE FIRST DAY',battleLog:'',decisions:[]};game.mode='story';persist();render()}
 function scene(){const s=game.state;const loc=floors[s.floor-1][0];s.location=loc;if(s.storyKey==='opening')return {title:'THE FIRST DAY',label:'NOVEMBER 6, 2022 · FLOOR 1',text:`I remember the way the light caught the rooftops of the Starting City. Ten thousand of us stood beneath the floating castle, laughing, testing the menus, pretending the world beyond the plaza was just another game.

Then the sky turned the color of blood. A colossal figure in a red hood appeared above the city. The system menu vanished from my sight.

“Players of Sword Art Online. I welcome you to my world.” Akihiko Kayaba’s voice was calm, impossibly clear. “You may have noticed that the logout button has disappeared. This is not a malfunction.”

Around me, voices rose into panic. Someone fell to their knees. A black-haired player near the edge of the crowd—Kirito, I’d later learn—was already watching the exits, calculating. A red-haired girl stood rigid, eyes fixed on the sky. “If we clear all one hundred floors,” Kayaba continued, “you will be freed. If your HP reaches zero here, your NerveGear will destroy your brain in the real world.”

My hand found the plain ${esc(s.weapon).toLowerCase()} at my side. It felt suddenly, terribly real. What I do next is mine to choose.`,choices:['Push through the crowd toward the city gate. I need space to think.','Look for the red-haired player; she seems as shocked as I am.','Find the black-haired solo player and ask what he knows.','Stay close to the plaza. Help someone who is panicking.']};
 if(s.storyKey==='afterIntro')return {title:'A CITY OF STRANGERS',label:'STARTING CITY · DAY ONE',text:`The plaza does not empty all at once. It fractures—some sprint toward the gate, others cling together beneath Kayaba’s fading image. The castle hangs above us, impossibly vast.

I have a basic weapon, a few starter supplies, and no real idea how to use either. My profile calls me “${esc(s.profile.personality)},” but that does not make the fear smaller. The outer fields begin just beyond the city walls. Somewhere out there, the first monsters are waiting.

I overhear a cheerful voice trying to rally a group near the fountain. “Name’s Klein! If we’re stuck in here, we might as well stick together!” A few steps away, Kirito is already moving toward the gate alone. The red-haired player has disappeared into the crowd.`,choices:['Approach Klein and offer to join his group.','Head for the gate and test my weapon alone.','Visit the item stalls before leaving the safe zone.','Ask the crowd if anyone knows where the red-haired player went.']};
-if(s.storyKey==='firstField')return {title:'THE VERDANT PLAINS',label:'FLOOR 1 · OUTER FIELD',text:`Outside the city, the grass rolls beneath a sky that looks too perfect to be kind. The safe-zone boundary glimmers behind me. A Grey Wolf pads between the low hills, ears angled toward the path. Its red HP bar hangs above its head.

I remember the warning: this is not a game anymore. I can retreat to the city if I need to, but the road forward will not open itself. A few players are visible in the distance; none close enough to save me from a bad decision.

The wolf has noticed me. It lowers its shoulders, preparing to lunge.`,choices:['Engage carefully. Watch its shoulders and look for an opening.','Keep distance and study its movement before committing.','Retreat to the safe zone. I’m not ready for a fight.']};
